export interface ConnectorConfig {
  pipedriveApiToken: string
  fetch: typeof fetch
}

export interface TypeformWebhookPayload {
  event_id: string
  event_type: string
  form_response: {
    form_id: string
    token: string
    submitted_at: string
    answers: Array<{
      type: string
      text?: string
      email?: string
      field: {
        id: string
        type: string
      }
    }>
  }
}

export interface HandleResult {
  organizationId: number
  personId: number
  dealId: number
}

function extractFieldValue(payload: TypeformWebhookPayload, fieldId: string): string | undefined {
  const answer = payload.form_response.answers.find(a => a.field.id === fieldId)
  if (!answer) return undefined
  return answer.type === 'email' ? answer.email : answer.text
}

export async function handle(payload: TypeformWebhookPayload, config: ConnectorConfig): Promise<HandleResult> {
  if (!payload.form_response?.answers?.length) {
    throw new Error('Missing required field: form_response.answers')
  }

  const name = extractFieldValue(payload, 'JwWggjAKtOkA')
  const email = extractFieldValue(payload, 'SMEUb7VJz92Q')
  const company = extractFieldValue(payload, 'company_field_id')

  if (!name) throw new Error('Missing required field: name (field id JwWggjAKtOkA)')
  if (!email) throw new Error('Missing required field: email (field id SMEUb7VJz92Q)')
  if (!company) throw new Error('Missing required field: company (field id company_field_id)')

  const authHeader = `Bearer ${config.pipedriveApiToken}`
  const headers = {
    'Authorization': authHeader,
    'Content-Type': 'application/json',
    'Accept': 'application/json'
  }

  const orgResponse = await config.fetch('https://api.pipedrive.com/v2/organizations', {
    method: 'POST',
    headers,
    body: JSON.stringify({ name: company })
  })

  if (!orgResponse.ok) {
    throw new Error(`Failed to create organization: ${orgResponse.status} ${orgResponse.statusText} at POST https://api.pipedrive.com/v2/organizations`)
  }

  const orgData = await orgResponse.json() as { success: boolean; data: { id: number } }
  if (!orgData.success || !orgData.data?.id) {
    throw new Error('Invalid organization creation response')
  }
  const organizationId = orgData.data.id

  const personResponse = await config.fetch('https://api.pipedrive.com/v2/persons', {
    method: 'POST',
    headers,
    body: JSON.stringify({
      name,
      email: [{ value: email, primary: true }],
      organization_id: organizationId
    })
  })

  if (!personResponse.ok) {
    throw new Error(`Failed to create person: ${personResponse.status} ${personResponse.statusText} at POST https://api.pipedrive.com/v2/persons`)
  }

  const personData = await personResponse.json() as { success: boolean; data: { id: number } }
  if (!personData.success || !personData.data?.id) {
    throw new Error('Invalid person creation response')
  }
  const personId = personData.data.id

  const dealResponse = await config.fetch('https://api.pipedrive.com/v2/deals', {
    method: 'POST',
    headers,
    body: JSON.stringify({
      person_id: personId,
      title: 'New deal from Typeform',
      status: 'open'
    })
  })

  if (!dealResponse.ok) {
    throw new Error(`Failed to create deal: ${dealResponse.status} ${dealResponse.statusText} at POST https://api.pipedrive.com/v2/deals`)
  }

  const dealData = await dealResponse.json() as { success: boolean; data: { id: number } }
  if (!dealData.success || !dealData.data?.id) {
    throw new Error('Invalid deal creation response')
  }
  const dealId = dealData.data.id

  return { organizationId, personId, dealId }
}

